public class OperatingSystem
{	public static readonly OperatingSystem WINDOWS = new();
	public static readonly OperatingSystem LINUX = new();
	public static readonly OperatingSystem MAC_OS_X = new();
	public static readonly OperatingSystem FREE_BSD = new();
	public static readonly OperatingSystem OPEN_BSD = new();
	public static readonly OperatingSystem UNSUPPORTED = new();


	/**
	 * Do not access this property directly. Access using Platform class.
	 */
	public static readonly OperatingSystem CURRENT_OPERATING_SYSTEM = findCurrentOperatingSystem();

